document.addEventListener("DOMContentLoaded",function(){function n(){const n=parseFloat(document.getElementById("trip-duration").value)||0,e=parseFloat(document.getElementById("travelers").value)||1,t=parseFloat(document.getElementById("accommodation").value)||0,a=parseFloat(document.getElementById("food").value)||0,i=parseFloat(document.getElementById("transport").value)||0,o=parseFloat(document.getElementById("activities").value)||0,r=parseFloat(document.getElementById("miscellaneous").value)||0,l=parseFloat(document.getElementById("flights").value)||0,d=parseFloat(document.getElementById("visas").value)||0,c=parseFloat(document.getElementById("gear").value)||0,u=parseFloat(document.getElementById("emergency-buffer").value)||0;if(n<=0||e<=0)return s.innerHTML='<p style="color: red;">Please enter valid trip duration and number of travelers.</p>',void 0;const p=t+a+i+o+r,g=p*e,v=g*n,m=(l+d+c)*e,b=v+m,h=b*(u/100),y=b+h;let $,f,k;p<=25?($="Ultra Budget Backpacker",f="Hostels, street food, free activities",k=["Stay in hostel dorms","Cook your own meals","Use public transport","Free walking tours"]):p<=50?($="Budget Backpacker",f="Mix of hostels/budget hotels, local food",k=["Mix dorms and private rooms","Eat local restaurants","Use local transport","Some paid activities"]):p<=100?($="Mid-Range Backpacker",f="Private rooms, restaurants, paid activities",k=["Private hostel rooms","Restaurant meals","Taxis when needed","Popular tours"]):($="Comfort Backpacker",f="Hotels, dining out, tours",k=["Budget hotels","All restaurant meals","Convenient transport","Multiple tours"]);!function(n){const{duration:e,travelers:t,dailyPerPerson:a,dailyTotal:i,totalDailyCosts:o,totalOneTimeCosts:r,emergencyAmount:l,grandTotal:d,totalPerPerson:c,budgetCategory:u,budgetDescription:p,budgetTips:g,regionalComparison:v,breakdown:m}=n;s.innerHTML=`\n      <div class="result-section">\n        <h3>🎒 Your Backpacking Budget</h3>\n        \n        <div class="budget-overview">\n          <div class="budget-category">\n            <h4>${u}</h4>\n            <p>${p}</p>\n            <div class="daily-budget">$${a.toFixed(2)} per person per day</div>\n          </div>\n        </div>\n\n        <div class="budget-insights">\n          <div class="insight-cards">\n            <div class="insight-card success">\n              <h6>💰 Total Cost</h6>\n              <p class="big-number">$${d.toFixed(0)}</p>\n              <p class="insight-detail">complete trip budget</p>\n            </div>\n            \n            <div class="insight-card info">\n              <h6>👤 Per Person</h6>\n              <p class="big-number">$${c.toFixed(0)}</p>\n              <p class="insight-detail">individual cost</p>\n            </div>\n            \n            <div class="insight-card ${a<=50?"success":a<=100?"warning":"info"}">\n              <h6>📅 Daily Budget</h6>\n              <p class="big-number">$${a.toFixed(0)}</p>\n              <p class="insight-detail">per person per day</p>\n            </div>\n            \n            <div class="insight-card info">\n              <h6>⏰ Duration</h6>\n              <p class="big-number">${e}</p>\n              <p class="insight-detail">day${e>1?"s":""} total</p>\n            </div>\n            \n            <div class="insight-card info">\n              <h6>👥 Travelers</h6>\n              <p class="big-number">${t}</p>\n              <p class="insight-detail">people going</p>\n            </div>\n            \n            <div class="insight-card warning">\n              <h6>🚨 Emergency Fund</h6>\n              <p class="big-number">$${l.toFixed(0)}</p>\n              <p class="insight-detail">safety buffer</p>\n            </div>\n          </div>\n        </div>\n\n        <div class="result-grid">\n\n        <div class="cost-breakdown">\n          <h4>📊 Cost Breakdown</h4>\n          <div class="breakdown-grid">\n            <div class="breakdown-item">\n              <span class="category">Daily Costs (${e} days):</span>\n              <span class="amount">$${o.toFixed(2)}</span>\n            </div>\n            <div class="breakdown-sub">\n              <span>• Accommodation: $${(m.accommodation*t*e).toFixed(2)}</span>\n            </div>\n            <div class="breakdown-sub">\n              <span>• Food & Drinks: $${(m.food*t*e).toFixed(2)}</span>\n            </div>\n            <div class="breakdown-sub">\n              <span>• Transportation: $${(m.transport*t*e).toFixed(2)}</span>\n            </div>\n            <div class="breakdown-sub">\n              <span>• Activities: $${(m.activities*t*e).toFixed(2)}</span>\n            </div>\n            <div class="breakdown-sub">\n              <span>• Miscellaneous: $${(m.miscellaneous*t*e).toFixed(2)}</span>\n            </div>\n            \n            <div class="breakdown-item">\n              <span class="category">One-time Costs:</span>\n              <span class="amount">$${r.toFixed(2)}</span>\n            </div>\n            <div class="breakdown-sub">\n              <span>• Flights: $${m.flights.toFixed(2)}</span>\n            </div>\n            <div class="breakdown-sub">\n              <span>• Visas & Insurance: $${m.visas.toFixed(2)}</span>\n            </div>\n            <div class="breakdown-sub">\n              <span>• Gear & Equipment: $${m.gear.toFixed(2)}</span>\n            </div>\n          </div>\n        </div>\n\n        <div class="regional-comparison">\n          <h4>🌍 Your Budget vs. Popular Backpacking Regions</h4>\n          <div class="regions-grid">\n            ${v.map(n=>`\n              <div class="region ${n.suitable?"suitable":"challenging"}">\n                <strong>${n.region}</strong>\n                <span class="region-cost">${n.cost}</span>\n                <span class="suitability">${n.suitable?"✅ Good fit":"⚠️ May be tight"}</span>\n              </div>\n            `).join("")}\n          </div>\n        </div>\n\n        <div class="budget-tips">\n          <h4>💡 Tips for Your Budget Level</h4>\n          <ul>\n            ${g.map(n=>`<li>${n}</li>`).join("")}\n          </ul>\n        </div>\n\n        <div class="savings-suggestions">\n          <h4>💰 Ways to Reduce Costs</h4>\n          <ul>\n            <li><strong>Accommodation:</strong> Choose hostel dorms over private rooms</li>\n            <li><strong>Food:</strong> Cook in hostel kitchens, eat street food</li>\n            <li><strong>Transport:</strong> Use overnight buses/trains, walk more</li>\n            <li><strong>Activities:</strong> Look for free walking tours and hiking</li>\n            <li><strong>General:</strong> Travel slower, avoid tourist traps</li>\n          </ul>\n        </div>\n\n        <div class="packing-reminder">\n          <h4>🎯 Don't Forget</h4>\n          <ul>\n            <li>Keep emergency funds separate from daily spending money</li>\n            <li>Notify banks of your travel plans</li>\n            <li>Research visa requirements early</li>\n            <li>Consider travel insurance coverage limits</li>\n            <li>Download offline maps and translation apps</li>\n          </ul>\n        </div>\n      </div>\n    `}({duration:n,travelers:e,dailyPerPerson:p,dailyTotal:g,totalDailyCosts:v,totalOneTimeCosts:m,emergencyAmount:h,grandTotal:y,totalPerPerson:y/e,budgetCategory:$,budgetDescription:f,budgetTips:k,regionalComparison:[{region:"Southeast Asia",cost:"$15-30/day",suitable:p>=15&&p<=60},{region:"Central America",cost:"$20-40/day",suitable:p>=20&&p<=70},{region:"Eastern Europe",cost:"$25-50/day",suitable:p>=25&&p<=80},{region:"South America",cost:"$25-60/day",suitable:p>=25&&p<=90},{region:"Western Europe",cost:"$50-100/day",suitable:p>=50},{region:"Australia/New Zealand",cost:"$60-120/day",suitable:p>=60}],breakdown:{accommodation:t,food:a,transport:i,activities:o,miscellaneous:r,flights:l*e,visas:d*e,gear:c*e}})}const e=document.getElementById("travel-budget-form"),s=document.getElementById("travel-budget-result");e.addEventListener("submit",function(e){e.preventDefault(),n()});e.querySelectorAll('input[type="number"]').forEach(e=>{e.addEventListener("input",function(){(function(){const n=parseFloat(document.getElementById("trip-duration").value),e=parseFloat(document.getElementById("travelers").value);return n>0&&e>0})()&&n()})})});